-- 消防前端权限节点，不注册重复的 /fire 业务路由。
-- 先备份数据库，在测试环境审核执行；不会自动给角色授予权限。
START TRANSACTION;
SELECT '消防业务权限',0,20,'fire-permissions',1,1,'M','1','0','','monitor','admin',SYSDATE(),'仅用于角色权限配置；前端业务菜单为静态受控路由'
WHERE NOT EXISTS (SELECT 1 FROM sys_menu WHERE path='fire-permissions' AND parent_id=0);
SET @fire_permission_root=(SELECT menu_id FROM sys_menu WHERE path='fire-permissions' AND parent_id=0 LIMIT 1);
COMMIT;
